"""Output column contract for features: docs/feature_spec.md is generated from code, not written by hand."""

from __future__ import annotations

import argparse
import sys

from src.config import ROOT, load_params
from src.features.build import feature_sources, forbidden_columns

DOC_PATH = ROOT / "docs" / "feature_spec.md"


def render(params: dict) -> str:
    pol = params["leakage"]["policy"]
    lines = [
        "# Feature specification",
        "",
        "Generated by `python -m src.features.spec`; do not edit by hand.",
        "",
        f"- Leakage policy: `{pol}`. Forbidden raw columns: "
        + ", ".join(f"`{c}`" for c in sorted(forbidden_columns(params)))
        + ".",
        "- Correlation detector threshold: the value of `leakage.max_abs_corr` in `params.yaml`, "
        "not copied here.",
        "- All features are float64. Column order is fixed and does not depend on the data.",
        "- Features are computed only from columns in the customer's own row; the label is never read.",
        "",
        "| Feature | Source columns |",
        "|---|---|",
    ]
    for name, sources in feature_sources(params).items():
        lines.append(f"| `{name}` | {', '.join(f'`{s}`' for s in sources)} |")
    return "\n".join(lines) + "\n"


def main(argv=None) -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args(argv)
    text = render(load_params())
    if args.check:
        same = DOC_PATH.exists() and DOC_PATH.read_text(encoding="utf-8") == text
        print(
            "feature_spec.md MATCHES the generator" if same else "feature_spec.md DIFFERS from the generator"
        )
        return 0 if same else 1
    DOC_PATH.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {DOC_PATH}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
